151	func cmdSweep(args []string) int {
152		fs := flagSet("sweep")
153		sweepFile := fs.String("sweep-plan", "", "Path to sweep plan YAML (default: scripts/benchmark/terminalbench-2-1-sweep.yaml)")
154		phaseID := fs.String("phase", "all", "Phase to run: canary, local-qwen, sonnet-comparison, gpt-comparison, or all")
155		dryRun := fs.Bool("dry-run", false, "Print plan without launching Harbor or any matrix run")
156		workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
157		out := fs.String("out", "", "Output directory (default: benchmark-results/sweep-<timestamp> under work-dir)")
158		resume := fs.Bool("resume", true, "Skip terminal cells (default: true per sweep plan defaults)")
159		forceRerun := fs.Bool("force-rerun", false, "Rerun even terminal cells")
160		tasksDir := fs.String("tasks-dir", "", "Path to TB-2.1 tasks directory; enables Harbor-graded runs")
161		budgetUSD := fs.Float64("budget-usd", 0, "Total sweep budget in USD (0 = no cap)")
162		perRunBudgetUSD := fs.Float64("per-run-budget-usd", 0, "Per-run budget cap in USD (0 = no cap)")
163		matrixJobsManaged := fs.Int("matrix-jobs-managed", 1, "Concurrent cells per managed-provider lane (default 1; increase subject to rate caps)")
164		if err := fs.Parse(args); err != nil {
165			return 2
166		}
167	
168		wd := resolveWorkDir(*workDir)
169	
170		planPath := *sweepFile
171		if planPath == "" {
172			planPath = filepath.Join(wd, defaultSweepPlanPath)
173		} else if !filepath.IsAbs(planPath) {
174			planPath = filepath.Join(wd, planPath)
175		}
176	
177		plan, err := loadSweepPlan(planPath)
178		if err != nil {
179			fmt.Fprintf(os.Stderr, "%s sweep: load plan %s: %v\n", benchCommandName(), planPath, err)
180			return 1
181		}
182	
183		phases, err := selectSweepPhases(plan, *phaseID)
184		if err != nil {
185			fmt.Fprintf(os.Stderr, "%s sweep: %v\n", benchCommandName(), err)
186			return 2
187		}
188	
189		outDir := *out
190		if outDir == "" {
191			outDir = filepath.Join(wd, "benchmark-results", "sweep-"+time.Now().UTC().Format("20060102T150405Z"))
192		} else if !filepath.IsAbs(outDir) {
193			outDir = filepath.Join(wd, outDir)
194		}
195	
196		opts := sweepRunOpts{
197			plan:              plan,
198			wd:                wd,
199			outDir:            outDir,
200			resume:            *resume,
201			forceRerun:        *forceRerun,
202			tasksDir:          *tasksDir,
203			budgetUSD:         *budgetUSD,
204			perRunBudgetUSD:   *perRunBudgetUSD,
205			matrixJobsManaged: *matrixJobsManaged,
206			rgByID:            sweepRGMap(plan),
207			laneByID:          sweepLaneMap(plan),
208			cgByLane:          sweepCGByLane(plan),
209			cgTypeByID:        sweepCGTypeMap(plan),
210		}
211	
212		for _, phase := range phases {
213			if *dryRun {
214				if code := printSweepDryRun(opts, phase); code != 0 {
215					return code
216				}
217			} else {
218				if code := runSweepPhase(opts, phase); code != 0 {
219					return code
220				}
221			}
222		}
223		return 0
224	}
