309	func runSweepPhase(opts sweepRunOpts, phase sweepPhase) int {
310		reps := phase.Reps
311		if reps == 0 {
312			reps = opts.plan.Defaults.Reps
313		}
314		subsetPath := sweepResolveSubsetPath(opts.wd, phase.Subset)
315	
316		// Per-resource-group semaphores enforce max_concurrency across concurrent lane goroutines.
317		rgSems := make(map[string]chan struct{}, len(opts.plan.ResourceGroups))
318		for _, rg := range opts.plan.ResourceGroups {
319			cap := rg.MaxConcurrency
320			if cap < 1 {
321				cap = 1
322			}
323			rgSems[rg.ID] = make(chan struct{}, cap)
324		}
325	
326		outcomes := make([]sweepLaneOutcome, len(phase.Lanes))
327		var wg sync.WaitGroup
328	
329		for i, laneID := range phase.Lanes {
330			lane, ok := opts.laneByID[laneID]
331			if !ok {
332				fmt.Fprintf(os.Stderr, "%s sweep: lane %q not found in plan\n", benchCommandName(), laneID)
333				return 1
334			}
335			rg, ok := opts.rgByID[lane.ResourceGroup]
336			if !ok {
337				fmt.Fprintf(os.Stderr, "%s sweep: resource group %q not found for lane %s\n",
338					benchCommandName(), lane.ResourceGroup, laneID)
339				return 1
340			}
341			sem, ok := rgSems[rg.ID]
342			if !ok {
343				sem = make(chan struct{}, 1)
344				rgSems[rg.ID] = sem
345			}
346	
347			wg.Add(1)
348			go func(i int, lane *sweepLane, rg *sweepResourceGroup, sem chan struct{}) {
349				defer wg.Done()
350				sem <- struct{}{}
351				defer func() { <-sem }()
352	
353				laneOutDir := filepath.Join(opts.outDir, phase.ID, lane.ID)
354				jobs := 1
355				if rg.MaxConcurrency > 1 && opts.matrixJobsManaged > 1 {
356					jobs = opts.matrixJobsManaged
357				}
358				matrixArgs := buildSweepMatrixArgs(opts, phase, lane, rg, subsetPath, laneOutDir, reps)
359				if jobs > 1 {
360					matrixArgs = append(matrixArgs, "--jobs", fmt.Sprintf("%d", jobs))
361				}
362	
363				meta := buildSweepLaneMeta(opts, phase, lane, rg, subsetPath, laneOutDir, reps, matrixArgs)
364				if err := os.MkdirAll(laneOutDir, 0o750); err != nil {
365					fmt.Fprintf(os.Stderr, "%s sweep: mkdir %s: %v\n", benchCommandName(), laneOutDir, err)
366					outcomes[i] = sweepLaneOutcome{laneID: lane.ID, code: 1, meta: meta}
367					return
368				}
369				if err := writeJSONAtomic(filepath.Join(laneOutDir, "sweep_lane_meta.json"), meta); err != nil {
370					fmt.Fprintf(os.Stderr, "%s sweep: write lane meta %s: %v\n", benchCommandName(), lane.ID, err)
371					outcomes[i] = sweepLaneOutcome{laneID: lane.ID, code: 1, meta: meta}
372					return
373				}
374	
375				fmt.Printf("[sweep] phase=%s lane=%s rg=%s (max_concurrency=%d) starting\n",
376					phase.ID, lane.ID, rg.ID, rg.MaxConcurrency)
377				code := cmdMatrix(matrixArgs)
378				fmt.Printf("[sweep] phase=%s lane=%s exit=%d\n", phase.ID, lane.ID, code)
379	
380				var mout *matrixOutput
381				matrixPath := filepath.Join(laneOutDir, "matrix.json")
382				if raw, err := os.ReadFile(matrixPath); err == nil { // #nosec G304 -- runner-owned output path
383					var mo matrixOutput
384					if json.Unmarshal(raw, &mo) == nil {
385						mout = &mo
386					}
387				}
388				outcomes[i] = sweepLaneOutcome{laneID: lane.ID, code: code, meta: meta, matrix: mout}
389			}(i, lane, rg, sem)
390		}
391		wg.Wait()
392	
393		printSweepPhaseSummary(phase.ID, outcomes)
394	
395		for _, o := range outcomes {
396			if o.code != 0 {
397				return o.code
398			}
399		}
400		return 0
401	}
