403	func printSweepPhaseSummary(phaseID string, outcomes []sweepLaneOutcome) {
404		fmt.Printf("\n=== Phase Summary: %s ===\n", phaseID)
405		hdr := fmt.Sprintf("%-42s %5s %5s %7s %10s %10s %10s %12s %14s %14s",
406			"Lane", "Pass", "Fail", "Invalid", "WallSec", "InToks", "OutToks", "Cost($)", "EffCost/Valid", "EffCost/Pass")
407		fmt.Println(hdr)
408		fmt.Println(strings.Repeat("-", len(hdr)))
409	
410		for _, o := range outcomes {
411			row := summarizeSweepLane(o.laneID, o.matrix)
412			effValid := "-"
413			effPass := "-"
414			if row.EffCostPerValid != nil {
415				effValid = fmt.Sprintf("$%.4f", *row.EffCostPerValid)
416			}
417			if row.EffCostPerPass != nil {
418				effPass = fmt.Sprintf("$%.4f", *row.EffCostPerPass)
419			}
420			fmt.Printf("%-42s %5d %5d %7d %10.1f %10d %10d %12.4f %14s %14s\n",
421				truncStr(o.laneID, 42),
422				row.NPasses,
423				row.NValid-row.NPasses,
424				row.NInvalid,
425				row.WallSeconds,
426				row.InputTokens,
427				row.OutputTokens,
428				row.CostUSD,
429				effValid,
430				effPass,
431			)
432		}
433		fmt.Println()
434	}
