436	func summarizeSweepLane(laneID string, mout *matrixOutput) sweepSummaryRow {
437		row := sweepSummaryRow{LaneID: laneID}
438		if mout == nil {
439			return row
440		}
441		for _, run := range mout.Runs {
442			row.NRuns++
443			row.WallSeconds += floatVal(run.WallSeconds)
444			row.InputTokens += intValue(run.InputTokens)
445			row.OutputTokens += intValue(run.OutputTokens)
446			row.CachedTokens += intValue(run.CachedInputTokens)
447			row.CostUSD += run.CostUSD
448			if ic := classifyMatrixInvalid(run); ic != "" {
449				row.NInvalid++
450				if row.InvalidCounts == nil {
451					row.InvalidCounts = map[string]int{}
452				}
453				row.InvalidCounts[ic]++
454			} else {
455				row.NValid++
456				if run.Reward != nil && *run.Reward == 1 {
457					row.NPasses++
458				}
459			}
460		}
461		if row.NValid > 0 {
462			v := row.CostUSD / float64(row.NValid)
463			row.EffCostPerValid = &v
464		}
465		if row.NPasses > 0 {
466			v := row.CostUSD / float64(row.NPasses)
467			row.EffCostPerPass = &v
468		}
469		return row
470	}
