486	// buildSweepMatrixArgs constructs the argument slice for cmdMatrix for a given lane.
487	func buildSweepMatrixArgs(opts sweepRunOpts, phase sweepPhase, lane *sweepLane, rg *sweepResourceGroup, subsetPath, laneOutDir string, reps int) []string {
488		args := []string{
489			"--work-dir", opts.wd,
490			"--subset", subsetPath,
491			"--profiles", lane.ProfileID,
492			"--harnesses", "fiz",
493			"--reps", fmt.Sprintf("%d", reps),
494			"--out", laneOutDir,
495		}
496		if opts.resume {
497			args = append(args, "--resume")
498		}
499		if opts.forceRerun {
500			args = append(args, "--force-rerun")
501		}
502		if opts.tasksDir != "" {
503			args = append(args, "--tasks-dir", opts.tasksDir)
504		}
505		if opts.budgetUSD > 0 {
506			args = append(args, "--budget-usd", fmt.Sprintf("%g", opts.budgetUSD))
507		}
508		// Apply resource-group per-run budget cap when present and no stricter flag is set.
509		if rg.Budget != nil && rg.Budget.PerRunUSDCap > 0 && opts.perRunBudgetUSD == 0 {
510			args = append(args, "--per-run-budget-usd", fmt.Sprintf("%g", rg.Budget.PerRunUSDCap))
511		} else if opts.perRunBudgetUSD > 0 {
512			args = append(args, "--per-run-budget-usd", fmt.Sprintf("%g", opts.perRunBudgetUSD))
513		}
514		return args
515	}
