517	func buildSweepLaneMeta(opts sweepRunOpts, phase sweepPhase, lane *sweepLane, rg *sweepResourceGroup, subsetPath, laneOutDir string, reps int, matrixArgs []string) sweepLaneMeta {
518		cgs := opts.cgByLane[lane.ID]
519		var cgTypes []string
520		for _, cgID := range cgs {
521			if t, ok := opts.cgTypeByID[cgID]; ok {
522				cgTypes = append(cgTypes, t)
523			}
524		}
525	
526		cmd := append([]string{benchCommandName(), "matrix"}, matrixArgs...)
527	
528		// Redact runtime API key values from fizeau_env; keep env var name references.
529		safeEnv := make(map[string]string, len(lane.FizeauEnv))
530		for k, v := range lane.FizeauEnv {
531			upper := strings.ToUpper(k)
532			if strings.HasSuffix(upper, "_API_KEY") || strings.HasSuffix(upper, "_SECRET") {
533				safeEnv[k] = "<redacted>"
534			} else {
535				safeEnv[k] = v
536			}
537		}
538	
539		return sweepLaneMeta{
540			Dataset:          opts.plan.Dataset,
541			DatasetVersion:   "2.1",
542			SubsetID:         phase.Subset,
543			SubsetPath:       subsetPath,
544			Phase:            phase.ID,
545			LaneID:           lane.ID,
546			ComparisonGroups: cgs,
547			ComparisonTypes:  cgTypes,
