648	// sweepMatrixSummary reads all matrix.json files under a sweep output directory
649	// and returns aggregated summary rows per lane for model-selection calculus.
650	func sweepMatrixSummary(sweepOutDir string) ([]sweepSummaryRow, error) {
651		entries, err := os.ReadDir(sweepOutDir)
652		if err != nil {
653			return nil, err
654		}
655		var rows []sweepSummaryRow
656		for _, phaseEntry := range entries {
657			if !phaseEntry.IsDir() {
658				continue
659			}
660			phaseDir := filepath.Join(sweepOutDir, phaseEntry.Name())
661			laneEntries, err := os.ReadDir(phaseDir)
662			if err != nil {
663				continue
664			}
665			for _, laneEntry := range laneEntries {
666				if !laneEntry.IsDir() {
667					continue
668				}
669				matrixPath := filepath.Join(phaseDir, laneEntry.Name(), "matrix.json")
670				raw, err := os.ReadFile(matrixPath) // #nosec G304 -- runner-owned output path
671				if err != nil {
672					continue
673				}
674				var mout matrixOutput
675				if err := json.Unmarshal(raw, &mout); err != nil {
676					continue
677				}
678				row := summarizeSweepLane(laneEntry.Name(), &mout)
679				rows = append(rows, row)
680			}
681		}
682		sort.Slice(rows, func(i, j int) bool { return rows[i].LaneID < rows[j].LaneID })
683		return rows, nil
684	}
