540	// TestSweepResourceGroupSchedulingParallelizesIndependentGroups uses two lanes
541	// each in their own resource group to verify they can run in parallel.
542	func TestSweepResourceGroupSchedulingParallelizesIndependentGroups(t *testing.T) {
543		plan := &sweepPlan{
544			Dataset:  "test",
545			Defaults: sweepDefaults{Reps: 1},
546			ResourceGroups: []sweepResourceGroup{
547				{ID: "rg-a", MaxConcurrency: 1},
548				{ID: "rg-b", MaxConcurrency: 1},
549			},
550			Lanes: []sweepLane{
551				{ID: "lane-a", ResourceGroup: "rg-a"},
552				{ID: "lane-b", ResourceGroup: "rg-b"},
553			},
554		}
555	
556		rgSems := make(map[string]chan struct{})
557		for _, rg := range plan.ResourceGroups {
558			rgSems[rg.ID] = make(chan struct{}, rg.MaxConcurrency)
559		}
560		laneByID := sweepLaneMap(plan)
561		rgByID := sweepRGMap(plan)
562	
563		started := make(chan string, 2)
564		var wg sync.WaitGroup
565	
566		for _, laneID := range []string{"lane-a", "lane-b"} {
567			lane := laneByID[laneID]
568			rg := rgByID[lane.ResourceGroup]
569			sem := rgSems[rg.ID]
570	
571			wg.Add(1)
572			go func(lane *sweepLane, sem chan struct{}) {
573				defer wg.Done()
574				sem <- struct{}{}
575				defer func() { <-sem }()
576				started <- lane.ID
577				time.Sleep(20 * time.Millisecond)
578			}(lane, sem)
579		}
580	
581		// Both lanes should have started before either finishes (parallel execution).
582		timeout := time.After(500 * time.Millisecond)
583		var s1, s2 string
584		select {
585		case s1 = <-started:
586		case <-timeout:
587			t.Fatal("lane-a or lane-b never started")
588		}
589		select {
590		case s2 = <-started:
591		case <-timeout:
592			t.Fatalf("second lane never started (first was %s); independent resource groups should run in parallel", s1)
593		}
594		_ = s2
595		wg.Wait()
596	}
