609	// TestSweepSummarizeLaneWithMixedRuns verifies summarizeSweepLane correctly
610	// aggregates pass/fail/invalid counts and computes effective costs.
611	func TestSweepSummarizeLaneWithMixedRuns(t *testing.T) {
612		pass := 1
613		fail := 0
614		costPass := 2.0
615		costFail := 1.0
616	
617		mout := &matrixOutput{
618			Runs: []matrixRunReport{
619				{Harness: "fiz", ProfileID: "p", TaskID: "t1", Rep: 1,
620					FinalStatus: "graded_pass", Reward: &pass,
621					CostUSD: costPass, InputTokens: intPtr(1000), OutputTokens: intPtr(500)},
622				{Harness: "fiz", ProfileID: "p", TaskID: "t2", Rep: 1,
623					FinalStatus: "graded_fail", Reward: &fail,
624					CostUSD: costFail, InputTokens: intPtr(800), OutputTokens: intPtr(400)},
625				{Harness: "fiz", ProfileID: "p", TaskID: "t3", Rep: 1,
626					FinalStatus: "invalid_provider", InvalidClass: "invalid_provider",
627					CostUSD: 0},
628			},
629		}
630	
631		row := summarizeSweepLane("lane-x", mout)
632		if row.NRuns != 3 {
633			t.Errorf("NRuns = %d, want 3", row.NRuns)
634		}
635		if row.NValid != 2 {
636			t.Errorf("NValid = %d, want 2 (graded pass + fail)", row.NValid)
637		}
638		if row.NInvalid != 1 {
639			t.Errorf("NInvalid = %d, want 1", row.NInvalid)
640		}
641		if row.NPasses != 1 {
642			t.Errorf("NPasses = %d, want 1", row.NPasses)
643		}
644		totalCost := costPass + costFail
645		if row.CostUSD != totalCost {
646			t.Errorf("CostUSD = %f, want %f", row.CostUSD, totalCost)
647		}
648		if row.EffCostPerValid == nil {
649			t.Error("EffCostPerValid is nil, want non-nil")
650		} else {
651			want := totalCost / 2.0
652			if got := *row.EffCostPerValid; fmt.Sprintf("%.4f", got) != fmt.Sprintf("%.4f", want) {
653				t.Errorf("EffCostPerValid = %f, want %f", got, want)
654			}
655		}
656		if row.EffCostPerPass == nil {
657			t.Error("EffCostPerPass is nil, want non-nil")
658		} else {
659			want := totalCost / 1.0
660			if got := *row.EffCostPerPass; fmt.Sprintf("%.4f", got) != fmt.Sprintf("%.4f", want) {
661				t.Errorf("EffCostPerPass = %f, want %f", got, want)
662			}
663		}
664	}
